export const SPOCSPOCRoleKeyToLabel = {
  'Primary': 'Primary',
  'Alternate': 'Alternate'
} as const;
export type SPOCSPOCRoleKey = keyof typeof SPOCSPOCRoleKeyToLabel;

export interface SPOC {
  /**
   * @displayName SPOC ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName SPOC Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  sPOCName: string;
  /**
   * @displayName SPOC Email
   */
  email?: string;
  /**
   * @displayName Review Flag
   * @validationRule Required for create/update operations
   */
  reviewFlag: boolean;
  /**
   * @displayName Review Notes
   */
  reviewNotes?: string;
  /**
   * @displayName Section
   * @validationRule Required for create/update operations
   */
  section: string;
  /**
   * @displayName SPOC Role
   * @validationRule Required for create/update operations
   */
  sPOCRoleKey: SPOCSPOCRoleKey;
  /**
   * @displayName Supervisor Email
   */
  supervisorEmail?: string;
  /**
   * @displayName Supervisor Name
   */
  supervisorName?: string;
}

export const _SPOC = 'SPOC' as const;